package app.chompass.services.grounding

import android.app.Application
import android.content.Context
import app.chompass.models.NutrientSourceKind
import java.io.File
import kotlin.math.roundToInt
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

/**
 * Reader + mapping over the committed fixture packs (generated by
 * `scripts/build_usda_gtin_index.py --fixture` and
 * `scripts/build_off_country_index.py --fixture`): the shipped schema stays
 * compatible with [BarcodePackIndex], meta drives provenance, null columns
 * survive, and the pack → FoodAnalysis mapping matches the OFF barcode path.
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [33], application = Application::class)
class BarcodePackFixtureTest {
    private lateinit var appContext: Context

    @Before
    fun setUp() {
        appContext = RuntimeEnvironment.getApplication()
    }

    /** Copies a classpath fixture into filesDir/offline_index/ like the installer would. */
    private fun openFixture(resource: String, packId: String): BarcodePackIndex {
        val bytes = javaClass.getResourceAsStream("/offlinepack/$resource")?.readBytes()
            ?: throw AssertionError("fixture $resource missing from test resources")
        val file = File(File(appContext.filesDir, "offline_index"), "$packId.sqlite")
        file.parentFile?.mkdirs()
        file.writeBytes(bytes)
        return BarcodePackIndex(file).apply { open() }
    }

    @Test
    fun usdaFixture_lookupsMappingAndProvenance() {
        val index = openFixture("fixture_usda.sqlite", "usda-gtins")
        try {
            assertEquals("usda-gtins", index.meta("pack_id"))
            val row = index.lookup("016000147725")!!
            assertEquals("Vegetable Baked Snacks", row.name)
            assertEquals("PepsiCo", row.brand)
            assertEquals(536.0, row.kcalPer100g!!, 0.001)
            assertEquals(28.0, row.servingGrams!!, 0.001)
            assertNull(index.lookup("0000000000000"))

            val analysis = row.toFoodAnalysis(index)
            assertEquals("PepsiCo Vegetable Baked Snacks", analysis.name)
            assertEquals((536.0 * 28.0 / 100.0).roundToInt(), analysis.calories)
            assertEquals("serving", analysis.selectedServingUnit)
            assertEquals(NutrientSourceKind.USDA, analysis.grounding?.sourceKind)
            assertEquals("usda-gtins:fixture", analysis.grounding?.datasetVersion)
            assertEquals("016000147725", analysis.productMetadata?.barcode)
        } finally {
            index.close()
        }
    }

    @Test
    fun deFixture_nullMacrosSurviveAndOffSourceIsStamped() {
        val index = openFixture("fixture_de.sqlite", "off-de")
        try {
            assertEquals("off-de", index.meta("pack_id"))
            assertEquals(
                "Open Database Licence (ODbL) — Open Food Facts",
                index.meta("license"),
            )

            // Row with macros only (Erdbeeren fixture row carries no nutrients
            // beyond zeros): mapping must not crash on absent energy.
            val straw = index.lookup("4000417025006")!!
            assertEquals("Erdbeeren", straw.name)
            val strawAnalysis = straw.toFoodAnalysis(index)
            assertEquals("Gut & Günstig Erdbeeren", strawAnalysis.name)
            assertEquals(0, strawAnalysis.calories)

            val zero = index.lookup("5449000000996")!!
            val zeroAnalysis = zero.toFoodAnalysis(index)
            // Name already contains the brand → no prefix (OFF composition rule).
            assertEquals("Coca-Cola Zero", zeroAnalysis.name)
            assertEquals((0.3 * 330.0 / 100.0).roundToInt(), zeroAnalysis.calories)
            assertEquals(NutrientSourceKind.OPEN_FOOD_FACTS, zeroAnalysis.grounding?.sourceKind)
        } finally {
            index.close()
        }
    }
}
